def fill_tax_split(apps, schema_editor):
    """
    Existing bills: store the GST split they would get today.
    Sales: customers had no state yet -> same state (CGST + SGST).
    Purchases: supplier state vs shop state (IGST when different).
    Only GST split fields are written; amounts and totals are unchanged.
    """

    from pharma_app.shop_types import features_for_type
    from pharma_app.states import tax_fields

    Sale = apps.get_model("pharma_app", "Sale")
    Purchase = apps.get_model("pharma_app", "Purchase")

    for sale in Sale.objects.select_related("retailer").iterator():
        features = features_for_type(sale.retailer.shop_type)
        values = tax_fields(features, sale.retailer.state, "", sale.gst)
        Sale.objects.filter(pk=sale.pk).update(**values)

    for purchase in Purchase.objects.select_related("retailer", "supplier").iterator():
        features = features_for_type(purchase.retailer.shop_type)
        values = tax_fields(features, purchase.retailer.state, purchase.supplier.state, purchase.gst)
        Purchase.objects.filter(pk=purchase.pk).update(**values)

